import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.BBd5PKnH.js";const g=JSON.parse('{"title":"Redis","description":"","frontmatter":{},"headers":[],"relativePath":"notes/redis.md","filePath":"notes/redis.md"}'),a={name:"notes/redis.md"};function r(o,n,h,c,l,d){return e(),i("div",null,[...n[0]||(n[0]=[s('<h1 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h1><p>Redis là một <strong>in-memory database</strong>, lưu trữ dữ liệu dưới dạng các object (JSON) theo cặp <strong>key-value</strong> — gần như mọi thứ trong Redis đều là key-value pair.</p><p>Các database khác thường lưu dữ liệu trên <strong>disk</strong>, trong khi Redis lưu trên <strong>RAM</strong>, nên tốc độ đọc/ghi nhanh hơn rất nhiều (khoảng 1000 lần).</p><p><strong>Nhược điểm</strong>: nếu server sập, toàn bộ dữ liệu trong RAM sẽ bị mất (wiped out) vì không lưu persistent theo mặc định. Vì vậy Redis phù hợp nhất cho các loại dữ liệu mà người dùng truy cập thường xuyên nhưng ít bị thay đổi.</p><h2 id="vi-sao-redis-nhanh" tabindex="-1">Vì sao Redis nhanh? <a class="header-anchor" href="#vi-sao-redis-nhanh" aria-label="Permalink to &quot;Vì sao Redis nhanh?&quot;">​</a></h2><ul><li>Lưu dữ liệu trên <strong>RAM</strong> thay vì disk.</li><li><strong>Single-threaded</strong> — kiến trúc đơn giản hơn so với các hệ cơ sở dữ liệu đa luồng.</li></ul><h3 id="vay-redis-xu-ly-nhieu-request-cung-luc-bang-cach-nao-neu-chi-chay-đon-luong" tabindex="-1">Vậy Redis xử lý nhiều request cùng lúc bằng cách nào nếu chỉ chạy đơn luồng? <a class="header-anchor" href="#vay-redis-xu-ly-nhieu-request-cung-luc-bang-cach-nao-neu-chi-chay-đon-luong" aria-label="Permalink to &quot;Vậy Redis xử lý nhiều request cùng lúc bằng cách nào nếu chỉ chạy đơn luồng?&quot;">​</a></h3><p>Nhờ cơ chế <strong>I/O multiplexing</strong> kết hợp <strong>event loop</strong>: thay vì tạo thread riêng cho từng kết nối, Redis dùng một vòng lặp sự kiện để theo dõi nhiều kết nối I/O cùng lúc và xử lý tuần tự các sự kiện sẵn sàng, nên vẫn phục vụ được nhiều client đồng thời mà không cần đa luồng.</p>',8)])])}const p=t(a,[["render",r]]);export{g as __pageData,p as default};
